#!/usr/bin/env node
/**
 * patch-hero-v2.mjs
 * Run from the project root:  node patch-hero-v2.mjs
 * Undo:                       node patch-hero-v2.mjs --restore
 *
 * Builds on patch-cooper-hewitt.mjs (already in your repo). This one:
 *  1. Removes the Threads background from the hero (plain #EBE9E1 stays)
 *  2. Changes the hero headline to BUILDING WHAT / MOVES YOU / FORWARD.  (all caps, centered)
 *  3. Adds the tight #D23412 highlight on BUILDING and FORWARD.
 *  4. Swaps in corrected font files (consistent vertical metrics so the highlight fits the
 *     capitals in every browser; renamed "Hewitt Web" as the font license requires)
 *
 * Idempotent. Every anchor is checked before anything is written; a mismatch aborts untouched.
 */
import fs from "node:fs";
import path from "node:path";

const FONTS = {
  "HewittWeb-Book.woff2": "",
  "HewittWeb-Medium.woff2": "",
  "HewittWeb-Semibold.woff2": "",
  "HewittWeb-Bold.woff2": "",
  "HewittWeb-Heavy.woff2": ""
};

const ROOT = process.cwd();
const MARK = "hero-v2:applied";
const BACKUP_DIR = path.join(ROOT, ".patch-backups", "hero-v2");
const P = (...a) => path.join(ROOT, ...a);
const FILES = ["app/layout.js", "app/page.js", "app/globals.css"];
const OLD_FONTS = ["Book", "Medium", "Semibold", "Bold", "Heavy"].map((w) => `CooperHewitt-${w}.woff2`);
const bakName = (f) => path.join(BACKUP_DIR, f.replace(/[\\/]/g, "__") + ".bak");

function fail(msg) {
  console.error("\n✖ " + msg + "\nNothing was written.");
  process.exit(1);
}

if (!fs.existsSync(P("app", "layout.js")) || !fs.existsSync(P("app", "page.js"))) {
  fail("Run this from the project root (the folder that contains app/ and package.json).");
}

// ── Restore ────────────────────────────────────────────────────────────────
if (process.argv.includes("--restore")) {
  let n = 0;
  for (const f of FILES) {
    if (fs.existsSync(bakName(f))) {
      fs.copyFileSync(bakName(f), P(f));
      n++;
      console.log("↩ restored " + f);
    }
  }
  for (const name of OLD_FONTS) {
    const b = bakName("app/fonts/" + name);
    if (fs.existsSync(b)) fs.copyFileSync(b, P("app", "fonts", name));
  }
  for (const name of Object.keys(FONTS)) fs.rmSync(P("app", "fonts", name), { force: true });
  console.log(n ? "\nRestored to the state after patch-cooper-hewitt.mjs." : "No backups found, nothing to restore.");
  process.exit(0);
}

const countOf = (src, s) => src.split(s).length - 1;
function replaceOnce(src, from, to, label) {
  const c = countOf(src, from);
  if (c !== 1) fail(`Anchor "${label}" matched ${c} time(s), expected 1.`);
  return src.replace(from, () => to);
}
function regexOnce(src, re, to, label) {
  const m = src.match(new RegExp(re.source, re.flags.includes("g") ? re.flags : re.flags + "g"));
  if (!m || m.length !== 1) fail(`Anchor "${label}" matched ${m ? m.length : 0} time(s), expected 1.`);
  return src.replace(re, () => to);
}

// ── Edits ──────────────────────────────────────────────────────────────────
function patchLayout(src) {
  if (!src.includes("cooper-hewitt:applied")) fail("Run patch-cooper-hewitt.mjs first (font setup not found in layout.js).");
  const c = countOf(src, "./fonts/CooperHewitt-");
  if (c !== 5) fail(`layout.js: expected 5 font paths, found ${c}.`);
  src = src.split("./fonts/CooperHewitt-").join("./fonts/HewittWeb-");
  src = replaceOnce(
    src,
    "// Cooper Hewitt (SIL OFL): one family drives both --font-display and --font-body",
    "// Cooper Hewitt, renamed web build \"Hewitt Web\" (SIL OFL, see ./fonts/OFL.txt): drives --font-display and --font-body",
    "layout: font comment"
  );
  return src + `\n// ${MARK}\n`;
}

function patchPage(src) {
  src = replaceOnce(src, 'import Threads from "./Threads";\n', "", "page: Threads import");
  if (countOf(src, "<Threads") !== 1) fail('page: expected exactly one <Threads usage.');

  // 1. hero background: drop threads + the fade overlay, keep the plain background
  src = regexOnce(
    src,
    /[ \t]*\{\/\* hero-threads:start \*\/\}[\s\S]*?\{\/\* hero-threads:end \*\/\}/,
    `      {/* hero-bg: plain background (threads removed) */}
      <div aria-hidden="true" className="absolute inset-0 z-0 pointer-events-none" style={{ background: LIGHT.bg }} />`,
    "page: hero threads block"
  );

  // 2. headline classes (sizing, caps, tracking now live in .hero-title in globals.css)
  src = regexOnce(
    src,
    /className="text-\[clamp\(2\.6rem,9\.5vw,8\.5rem\)\] font-display font-extrabold leading-none (?:uppercase )?tracking-\[-0\.03em\] text-center"/,
    'className="hero-title font-display font-extrabold text-center"',
    "page: hero h1 className"
  );

  // 3. headline text + highlight
  src = regexOnce(
    src,
    /[ \t]*<span className="block" style=\{\{ color: "var\(--h-text\)" \}\}>Building Systems<\/span>\s*<span[^\n]*>That Make Ideas<\/span>\s*<span[^\n]*>Work<span[^\n]*<\/span><\/span>/,
    `          <span className="hero-line"><span className="hero-hl">Building</span> What</span>
          <span className="hero-line">Moves You</span>
          <span className="hero-line"><span className="hero-hl">Forward.</span></span>`,
    "page: hero headline lines"
  );
  return src + `\n/* ${MARK} */\n`;
}

function patchGlobals(src) {
  return (
    src +
    `
/* hero-v2:start */
/* Hero headline: all caps, sized so the widest line ("BUILDING WHAT") always fits the screen */
.hero-title {
  color: var(--h-text);
  text-transform: uppercase;
  letter-spacing: -0.02em;
  line-height: 1;
  font-synthesis: none;
  font-size: min(calc((100vw - 3rem) / 7.6), 10.5rem);
}
@media (min-width: 768px) {
  .hero-title { font-size: min(calc((100vw - 10rem) / 7.6), 10.5rem); }
}
.hero-line { display: block; white-space: nowrap; }
/* Red highlight hugs the capitals: cap height + 0.03em overshoot, no outer margin */
.hero-hl {
  color: #FFF4EA;
  padding: 0 0.03em 0 0.01em;
  background: linear-gradient(#D23412, #D23412) 0 0.01em / 100% 0.84em no-repeat;
}
/* hero-v2:end */
/* ${MARK} */
`
  );
}

const PATCHERS = { "app/layout.js": patchLayout, "app/page.js": patchPage, "app/globals.css": patchGlobals };

// ── Plan in memory ─────────────────────────────────────────────────────────
const pending = [];
const skipped = [];
for (const f of FILES) {
  const src = fs.readFileSync(P(f), "utf8");
  if (src.includes(MARK)) skipped.push(f);
  else pending.push([f, PATCHERS[f](src)]);
}

// ── Write ──────────────────────────────────────────────────────────────────
fs.mkdirSync(BACKUP_DIR, { recursive: true });
for (const [f, out] of pending) {
  if (!fs.existsSync(bakName(f))) fs.copyFileSync(P(f), bakName(f));
  fs.writeFileSync(P(f), out);
  console.log("✔ patched " + f);
}
for (const f of skipped) console.log("• already patched " + f);

fs.mkdirSync(P("app", "fonts"), { recursive: true });
for (const name of OLD_FONTS) {
  const old = P("app", "fonts", name);
  if (fs.existsSync(old)) {
    const b = bakName("app/fonts/" + name);
    if (!fs.existsSync(b)) fs.copyFileSync(old, b);
    fs.rmSync(old);
  }
}
for (const [name, b64] of Object.entries(FONTS)) {
  fs.writeFileSync(P("app", "fonts", name), Buffer.from(b64, "base64"));
}
console.log("✔ app/fonts now has HewittWeb-*.woff2 (" + Object.keys(FONTS).length + " files)");

console.log(`
Done. Backups: .patch-backups/hero-v2/   Undo: node patch-hero-v2.mjs --restore
Restart "npm run dev". Threads.jsx / Threads.css are no longer imported; delete them if you like.`);
